import sys
import time

def check_sounddevice():
    try:
        import sounddevice as sd
        import numpy as np

        print("=" * 60)
        print("🎙️  DANH SÁCH THIẾT BỊ MICROPHONE TRÊN MÁY TÍNH:")
        print("=" * 60)
        devices = sd.query_devices()
        input_devices = [d for d in devices if d['max_input_channels'] > 0]

        if not input_devices:
            print("❌ Không tìm thấy thiết bị Microphone (Input Device) nào!")
            return

        for i, d in enumerate(devices):
            if d['max_input_channels'] > 0:
                default_tag = " (Mặc định)" if i == sd.default.device[0] else ""
                print(f"[{i}] {d['name']}{default_tag} - Kênh: {d['max_input_channels']}")

        print("\n" + "=" * 60)
        print("🔴 ĐANG KIỂM TRA MỨC ÂM THANH MICROPHONE MẶC ĐỊNH (Nhấn Ctrl+C để dừng)...")
        print("=" * 60)

        def audio_callback(indata, frames, time_info, status):
            if status:
                print(status, file=sys.stderr)
            volume_norm = np.linalg.norm(indata) * 10
            bar_len = int(volume_norm)
            meter = "█" * min(bar_len, 40)
            print(f"\rÂm lượng: [{meter:<40}] {volume_norm:.2f}", end="", flush=True)

        with sd.InputStream(callback=audio_callback):
            while True:
                time.sleep(0.1)

    except ImportError:
        print("⚠️ Thiếu thư viện 'sounddevice' hoặc 'numpy'. Sẽ tiến hành kiểm tra hoặc cài đặt.")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\n\n✅ Đã dừng kiểm tra Microphone!")
    except Exception as e:
        print(f"\n❌ Gặp lỗi trong quá trình kiểm tra: {e}")

if __name__ == "__main__":
    check_sounddevice()
